    try:
        seen = set()
        min_bases = []

        def add_bases(cls):
            if cls not in seen:
                seen.add(cls)
                for base in cls.__bases__:
                    add_bases(base)
                min_bases.insert(0, cls)

        for cls in classes:
            add_bases(cls)

        # Remove duplicates while preserving order
        return list(dict.fromkeys(min_bases[::-1]))
    except Exception as e:
        raise ValueError("Error processing base classes: " + str(e))

