def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise ValueError("SQL must be a string or bytes")

    if not isinstance(params, (Mapping, Sequence)):
        raise ValueError("Parameters must be a mapping or sequence")

    in_style = getattr(self, 'in_style', 'named')
    out_style = getattr(self, 'out_style', 'named')

    if in_style == out_style:
        return sql, params

    if in_style == 'named':
        if not isinstance(params, Mapping):
            raise ValueError("Named parameters must be provided as a mapping")

        if out_style == 'qmark':
            placeholders = list(params.keys())
            sql = sql.replace('%(', '?')
            params = [params[p] for p in placeholders]
        elif out_style == 'numeric':
            sql = sql.replace('%(', ':')
            numeric_params = {i + 1: value for i, value in enumerate(params.values())}
            sql = re.sub(r':(\w+)', lambda m: str(numeric_params[int(m.group(1))]), sql)
            params = list(numeric_params.values())
        elif out_style == 'format':
            sql = sql.replace('%(', '{}')
            params = [params[key] for key in sorted(params.keys())]
        elif out_style == 'pyformat':
            sql = sql.replace('%(', '%(')
        else:
            raise ValueError(f"Unsupported out-style: {out_style}")

    elif in_style == 'qmark':
        if not isinstance(params, Sequence):
            raise ValueError("Ordinal parameters must be provided as a sequence")

        if out_style == 'named':
            placeholders = [f':{i + 1}' for i in range(len(params))]
            sql = '; '.join(f"{part}{placeholders[i]}" for i, part in enumerate(sql.split('?')) if part != '')
            params = {i + 1: value for i, value in enumerate(params)}
        elif out_style == 'numeric':
            placeholders = [f':{i + 1}' for i in range(len(params))]
            sql = '; '.join(f"{part}{placeholders[i]}" for i, part in enumerate(sql.split('?')) if part != '')
            params = {i + 1: value for i, value in enumerate(params)}
        elif out_style == 'format':
            sql = sql.replace('?', '{}')
        elif out_style == 'pyformat':
            placeholders = [f'%({i + 1})s' for i in range(len(params))]
            sql = '; '.join(f"{part}{placeholders[i]}" for i, part in enumerate(sql.split('?')) if part != '')
        else:
            raise ValueError(f"Unsupported out-style: {out_style}")

    elif in_style == 'numeric':
        if not isinstance(params, Sequence):
            raise ValueError("Ordinal parameters must be provided as a sequence")

        if out_style == 'named':
            placeholders = [f':{i + 1}' for i in range(len(params))]
            sql = '; '.join(f"{part}{placeholders[i]}" for i, part in enumerate(sql.split(':')) if part != '')
            params = {i + 1: value for i, value in enumerate(params)}
        elif out_style == 'qmark':
            sql = sql.replace(':', '?')
        elif out_style == 'format':
            sql = sql.replace(':', '{}')
        elif out_style == 'pyformat':
            placeholders = [f'%({i + 1})s' for i in range(len(params))]
            sql = '; '.join(f"{part}{placeholders[i]}" for i, part in enumerate(sql.split(':')) if part != '')
        else:
            raise ValueError(f"Unsupported out-style: {out_style}")

    elif in_style == 'format':
        if not isinstance(params, Sequence):
            raise ValueError("Ordinal parameters must be provided as a sequence")

        if out_style == 'named':
            placeholders = [f':{i + 1}' for i in range(len(params))]
            sql = '; '.join(f"{part}{placeholders[i]}" for i, part in enumerate(sql.split('{}')) if part != '')
            params = {i + 1: value for i, value in enumerate(params)}
        elif out_style == 'qmark':
            sql = sql.replace('{}', '?')
        elif out_style == 'numeric':
            placeholders = [f':{i + 1}' for i in range(len(params))]
            sql = '; '.join(f"{part}{placeholders[i]}" for i, part in enumerate(sql.split('{}')) if part != '')
        elif out_style == 'pyformat':
            placeholders = [f'%({i + 1})s' for i in range(len(params))]
            sql = '; '.join(f"{part}{placeholders[i]}" for i, part in enumerate(sql.split('{}')) if part != '')
        else:
            raise ValueError(f"Unsupported out-style: {out_style}")

    elif in_style == 'pyformat':
        if not isinstance(params, Mapping):
            raise ValueError("Pyformat parameters must be provided as a mapping")

        if out_style == 'named':
            sql = sql.replace('%%(', ':')
            sql = sql.replace('%)s', '')
        elif out_style == 'qmark':
            placeholders = list(params.keys())
            sql = sql.replace('%%(', '?')
            sql = sql.replace('%)s', '')
            params = [params[p] for p in placeholders]
        elif out_style == 'numeric':
            placeholders = list(params.keys())
            sql = sql.replace('%%(', ':')
            sql = sql.replace('%)s', '')
            numeric_params = {i + 1: params[placeholders[i]] for i in range(len(placeholders))}
            sql = re.sub(r':(\w+)', lambda m: str(numeric_params[int(m.group(1))]), sql)
            params = list(numeric_params.values())
        elif out_style == 'format':
            placeholders = list(params.keys())
            sql = sql.replace('%%(', '{}')
            sql = sql.replace('%)s', '')
            params = [params[p] for p in placeholders]
        else:
            raise ValueError(f"Unsupported out-style: {out_style}")

    else:
        raise ValueError(f"Unsupported in-style: {in_style}")

    return sql, params

def formatmany(
		self,
		sql: AnyStr,
		many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
	) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
		"""
		Convert the SQL query to use the out-style parameters instead of the
		in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*many_params* (:class:`~collections.abc.Iterable`) contains each set
		of in-style parameters (*params*).

		-	*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
			contains the set of in-style parameters. It maps each parameter
			(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
			is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
			If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
			*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	A :class:`list` containing each set of converted out-style
			parameters (:class:`dict` or :class:`list`).
		"""
		from_style = self.SQLParams.in_style
		to_style = self.SQLParams.out_style

		if from_style == to_style:
			return sql, list(many_params)

		try:
			if from_style == 'qmark':
				param_format = '?'
			elif from_style == 'numeric':
				param_format = ':{}'
			elif from_style == 'named':
				param_format = ':{}'
			elif from_style == 'format':
				param_format = '{}'
			elif from_style == 'pyformat':
				param_format = '%({})s'
			else:
				raise ValueError(f"Unsupported in-style: {from_style}")

			if to_style == 'qmark':
				new_param_format = '?'
				param_counter = 1
			elif to_style == 'numeric':
				new_param_format = ':{}'
				param_counter = 1
			elif to_style == 'named':
				new_param_format = ':{}'
			elif to_style == 'format':
				new_param_format = '{}'
			elif to_style == 'pyformat':
				new_param_format = '%({})s'
			else:
				raise ValueError(f"Unsupported out-style: {to_style}")

			new_sql_parts = []
			new_many_params = []
			start = 0
			param_index = 0
			for match in self._param_regex[from_style].finditer(sql):
				new_sql_parts.append(sql[start:match.start()])
				param = match.group(0)
				if from_style == 'format':
					param_name = param_index
				elif from_style in ('qmark', 'numeric', 'pyformat'):
					param_name = param_counter
				else:
					param_name = param[1:] if from_style == 'named' else param[1:-1]

				if isinstance(next(iter(many_params[0])), Mapping):
					new_param_name = next(iter(many_params[0])) if to_style == 'format' else f'{param_name}'
				else:
					new_param_name = param_counter if to_style in ('qmark', 'numeric', 'pyformat') else f'{param_name}'

				new_sql_parts.append(new_param_format.format(new_param_name))
				start = match.end()
				if from_style in ('qmark', 'numeric', 'pyformat'):
					param_counter += 1
				param_index += 1

			new_sql_parts.append(sql[start:])
			new_sql = ''.join(new_sql_parts)

			for params in many_params:
				if isinstance(params, Mapping):
					new_params = {}
					for key, value in params.items():
						if to_style in ('qmark', 'numeric', 'pyformat'):
							new_params[param_counter] = value
							param_counter += 1
						else:
							new_params[key] = value
				else:
					new_params = list(params)
				new_many_params.append(new_params)

			return new_sql, new_many_params

		except Exception as e:
			raise ValueError(f"Error converting SQL parameters: {e}")

def formatmany(
        self,
        sql: AnyStr,
        many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    import re
    from collections.abc import Iterable, Mapping, Sequence

    if not isinstance(sql, (str, bytes)):
        raise ValueError("sql must be a string or bytes")

    if not isinstance(many_params, Iterable):
        raise ValueError("many_params must be an iterable")

    out_style = self.SQLParams.out_style
    in_style = self.SQLParams.in_style

    if out_style == in_style:
        return sql, list(many_params)

    # Define regex pattern based on in_style
    if in_style in ('named', 'pyformat'):
        pattern = r':([a-zA-Z0-9_]+)'
    elif in_style in ('format', 'numeric'):
        pattern = r'%s'
    elif in_style == 'qmark':
        pattern = r'\?'
    else:
        raise ValueError(f"Unsupported in-style: {in_style}")

    formatted_sql = sql
    converted_params = []

    for params in many_params:
        if not isinstance(params, (Mapping, Sequence)):
            raise ValueError("Each set of params must be a Mapping or Sequence")

        if out_style in ('named', 'pyformat'):
            # Out-style is named, so no change needed in SQL
            new_params = params
        elif out_style in ('format', 'numeric'):
            # Out-style is numeric, convert params to list
            if isinstance(params, Mapping):
                new_params = [params[key] for key in sorted(params.keys(), key=lambda x: int(x) if isinstance(x, int) else float('inf'))]
            else:
                new_params = list(params)
        elif out_style == 'qmark':
            # Out-style is qmark, convert params to list
            if isinstance(params, Mapping):
                new_params = [params[key] for key in sorted(params.keys(), key=lambda x: int(x) if isinstance(x, int) else float('inf'))]
            else:
                new_params = list(params)

        # Replace in-style placeholders with out-style placeholders
        if out_style in ('named', 'pyformat'):
            # Named or pyformat out-style, no need to replace placeholders
            new_sql = sql
        elif out_style in ('format', 'numeric'):
            # Format or numeric out-style, replace placeholders with %s
            new_sql = re.sub(pattern, '%s', sql)
        elif out_style == 'qmark':
            # Qmark out-style, replace placeholders with ?
            if in_style == 'format':
                new_sql = re.sub(pattern, '?', sql)
            elif in_style == 'numeric':
                new_sql = '?' * len(new_params)
            else:
                new_sql = re.sub(pattern, '?', sql)

        formatted_sql = new_sql
        converted_params.append(new_params)

    # If out-style is format or numeric, all SQLs should be the same, so take the first one
    if out_style in ('format', 'numeric'):
        formatted_sql = new_sql

    return formatted_sql, converted_params

