def add_asset(self, basename, file_path):
    """
    Adds an asset to the internal dictionary with different file extensions.

    Args:
        basename (str): The base name of the file without the extension (e.g., "artigo02-gf03").
        file_path (str): The directory path where the files are located.

    Returns:
        dict: A dictionary mapping filenames with different extensions to their full file paths.
    """
    if not isinstance(basename, str) or not isinstance(file_path, str):
        raise ValueError("Both basename and file_path must be strings.")

    if not os.path.isdir(file_path):
        raise FileNotFoundError(f"The directory {file_path} does not exist.")

    extensions = ['.tiff', '.jpg', '.png']
    asset_dict = {}

    for ext in extensions:
        full_path = os.path.join(file_path, basename + ext)
        if os.path.exists(full_path):
            asset_dict[basename + ext] = full_path

    if not asset_dict:
        raise FileNotFoundError(f"No files found for basename {basename} with extensions {extensions} in directory {file_path}.")

    return asset_dict

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, str):
        raise ValueError("zip_path must be a string")

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            package_data = {}
            for file_info in z.infolist():
                filename = file_info.filename
                if filename.endswith('.xml'):
                    base_name = os.path.splitext(os.path.basename(filename))[0]
                    if base_name not in package_data:
                        package_data[base_name] = []
                    package_data[base_name].append({
                        'filename': filename,
                        'content': z.read(filename).decode('utf-8')
                    })
            return package_data
    except zipfile.BadZipFile:
        raise ValueError("Invalid zip file")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")

