def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent
    representation = f"{indent_str}<{self.__class__.__name__}>\n"
    try:
        for key, value in self.__dict__.items():
            if isinstance(value, (list, tuple, set)):
                representation += f"{indent_str}  {key}: [\n"
                for item in value:
                    if hasattr(item, 'pretty'):
                        representation += item.pretty(indent + 4, debug)
                    else:
                        representation += f"{indent_str}    {item}\n"
                representation += f"{indent_str}  ]\n"
            elif isinstance(value, dict):
                representation += f"{indent_str}  {key}: {{\n"
                for sub_key, sub_value in value.items():
                    if hasattr(sub_value, 'pretty'):
                        representation += sub_value.pretty(indent + 4, debug)
                    else:
                        representation += f"{indent_str}    {sub_key}: {sub_value}\n"
                representation += f"{indent_str}  }}\n"
            elif hasattr(value, 'pretty'):
                representation += f"{indent_str}  {key}: {value.pretty(indent + 2, debug)}\n"
            else:
                representation += f"{indent_str}  {key}: {value}\n"
    except AttributeError:
        representation += f"{indent_str}  (Unable to retrieve attributes for {self.__class__.__name__})"
    return representation

