def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    def apply_absorption(expr):
        if isinstance(expr, tuple) and len(expr) == 3:
            op, a, b = expr
            if op == '&':
                if isinstance(b, tuple) and b[0] == '|':
                    if a == b[1] or a == b[2]:
                        return a
                    if isinstance(b[1], tuple) and b[1][0] == '~' and b[1][1] == a:
                        return ('&', a, b[2])
                    if isinstance(b[2], tuple) and b[2][0] == '~' and b[2][1] == a:
                        return ('&', a, b[1])
            elif op == '|':
                if isinstance(b, tuple) and b[0] == '&':
                    if a == b[1] or a == b[2]:
                        return a
                    if isinstance(b[1], tuple) and b[1][0] == '~' and b[1][1] == a:
                        return ('|', a, b[2])
                    if isinstance(b[2], tuple) and b[2][0] == '~' and b[2][1] == a:
                        return ('|', a, b[1])
        return expr

    return [apply_absorption(arg) for arg in args]

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    from collections.abc import MutableSequence

    def is_expr(expr):
        # Simple check to determine if the expression is a tuple of the form (operator, operand1, operand2)
        return isinstance(expr, tuple) and len(expr) == 3 and expr[0] in ('&', '|')

    def absorb_expr(expr):
        if not is_expr(expr):
            return expr

        op, a, b = expr

        if is_expr(a) and a[0] == op:
            # A & (A | B) or A | (A & B)
            if (op == '&' and b == ('|', a[1], a[2])) or (op == '|' and b == ('&', a[1], a[2])):
                return a[1]

        if is_expr(b) and b[0] == op:
            # A & (B | A) or A | (B & A)
            if (op == '&' and a == ('|', b[1], b[2])) or (op == '|' and a == ('&', b[1], b[2])):
                return b[1]

        if is_expr(a) and a[0] == ('&' if op == '|' else '|'):
            # A | (~A & B) or A & (~A | B)
            if (op == '|' and a[1] == ('~', b[1])) or (op == '&' and a[1] == ('~', b[1])):
                return (op, a[2], b[2])
            # A | (B & ~A) or A & (B | ~A)
            if (op == '|' and a[2] == ('~', b[1])) or (op == '&' and a[2] == ('~', b[1])):
                return (op, a[1], b[2])

        # Recursively apply absorption to sub-expressions
        return (op, absorb_expr(a), absorb_expr(b))

    if not isinstance(args, MutableSequence):
        raise ValueError("args must be a sequence of expressions")

    return [absorb_expr(arg) for arg in args]

