    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    import argparse
    import sys

    parser = argparse.ArgumentParser(description='Parse command-line arguments.')
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Example subparser setup
    parser_a = subparsers.add_parser('subparser_a', help='Description of subparser A')
    parser_a.add_argument('--option_a', type=str, help='Option for subparser A')

    parser_b = subparsers.add_parser('subparser_b', help='Description of subparser B')
    parser_b.add_argument('--option_b', type=int, help='Option for subparser B')

    # Global arguments
    parser.add_argument('--global_option', type=float, help='Global option for all subparsers')

    try:
        parsed_args = parser.parse_args(args=unparsed_arguments or sys.argv[1:])
    except SystemExit:
        # If argparse encounters an error, it raises SystemExit. We catch it and return an empty dict.
        return {}

    result = {'global': argparse.Namespace()}
    for key, value in vars(parsed_args).items():
        if key == 'subparser_name':
            if value is not None:
                result[value] = argparse.Namespace()
        else:
            if parsed_args.subparser_name is None:
                setattr(result['global'], key, value)
            else:
                setattr(result[parsed_args.subparser_name], key, value)

    # Remove subparser_name from global namespace
    if 'subparser_name' in vars(result['global']):
        delattr(result['global'], 'subparser_name')

    return result

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            namespace, unknown_args = parser.parse_known_args(remaining_arguments)
            parsed_arguments[subparser_name] = namespace
            remaining_arguments = unknown_args
        except Exception as e:
            # If parsing fails for a subparser, store None and continue with others
            parsed_arguments[subparser_name] = None

    return parsed_arguments, remaining_arguments

