    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_results = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        try:
            namespace, args = subparser.parse_known_args(remaining_arguments)
            parsed_results[subparser_name] = namespace
            remaining_arguments = args
        except SystemExit:
            # If a subparser calls sys.exit(), it means there was a parsing error
            # We can choose to handle this or ignore it and continue with the next subparser
            continue

    return parsed_results, remaining_arguments

