def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import sys
    from borgmatic import cli, subcommands

    def build_completion_script(parser, cmd_name):
        comp_lines = []
        options = []

        for action in parser._actions:
            if isinstance(action, argparse._SubParsersAction):
                for choice, subparser in action.choices.items():
                    comp_lines.extend(build_completion_script(subparser, f"{cmd_name} {choice}"))
            else:
                for option in action.option_strings:
                    options.append(option)

        if options:
            comp_lines.append(f"    _arguments -s : \\")
            comp_lines.extend([f"        '({option})' \\" for option in options])
            comp_lines.append(f"        '::commands:{subcommands.choices}' \\")

        if cmd_name == "borgmatic":
            comp_lines.insert(0, f"_borgmatic() {{")
            comp_lines.append("}")
            comp_lines.append("compdef _borgmatic borgmatic")
        else:
            comp_lines.append(f"    {cmd_name} ;;")

        return comp_lines

    try:
        borgmatic_parser = cli.build_parser([subcommands.choices])
        completion_script = build_completion_script(borgmatic_parser, "borgmatic")
        return '\n'.join(completion_script)
    except Exception as e:
        print(f"An error occurred while generating the bash completion script: {e}", file=sys.stderr)
        return ""

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import borgmatic.commands
    import shlex

    def get_parser_commands(parser):
        try:
            subparsers_actions = [
                action for action in parser._actions
                if isinstance(action, argparse._SubParsersAction)
            ]
            return {subparser.dest: subparser.choices for subparser in subparsers_actions}
        except:
            return {}

    def get_parser_options(parser):
        options = []
        for action in parser._actions:
            if isinstance(action, argparse._HelpAction):
                continue
            if isinstance(action, argparse._SubParsersAction):
                continue
            if action.option_strings:
                options.extend(action.option_strings)
        return options

    def generate_subcommand_completion(parent_parser, commands, command_name, prefix=''):
        if not commands:
            return []
        completion = []
        for cmd, subparser in commands.items():
            full_command = f"{prefix} {cmd}".strip()
            completion.append(f"    {full_command})\n")
            completion.append(f"        {generate_parser_completion(subparser, prefix=full_command)}\n")
            completion.append(f"        ;;\n")
        return "".join(completion)

    def generate_parser_completion(parser, prefix=''):
        options = get_parser_options(parser)
        subcommands = get_parser_commands(parser)
        completion = ["    options=(", ", ".join(shlex.quote(opt) for opt in options), ")\n"]
        completion.append("    COMPREPLY=($(compgen -W \"${options[*]}\" -- \"$cur\"))\n")
        completion.append(generate_subcommand_completion(parser, subcommands, prefix))
        return "".join(completion)

    main_parser = borgmatic.commands.create_global_parser()
    subcommands = get_parser_commands(main_parser)

    script = [
        "# Completion script for borgmatic",
        "_borgmatic() {",
        "    local cur prev words cword",
        "    _init_completion || return",
        "",
        "    subcommands=( $(borgmatic --help 2>&1 | grep -oE '^\\s{2}\\w+') )",
        "",
        "    case $prev in",
        "        *)",
        "            case $cur in",
        "                -*)",
        generate_parser_completion(main_parser),
        "                ;;",
        "                *)",
        "                    COMPREPLY=($(compgen -W \"${subcommands[*]}\" -- \"$cur\"))",
        "                    ;;",
        "            esac",
        "            ;;",
        "    esac",
        "}",
        "complete -F _borgmatic borgmatic"
    ]

    return "\n".join(script)

def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import borgmatic.commands.arguments

    def argument_to_completion(arg):
        if arg.option_strings:
            return ' '.join(arg.option_strings)
        return arg.dest

    def subcommand_completion(subcommand, parser):
        options = []
        for action in parser._actions:
            options.append(argument_to_completion(action))
        return f"complete -W \"{' '.join(options)}\" borgmatic {' '.join(subcommand.strip().split()[1:])}"

    main_parser = borgmatic.commands.arguments.make_parsers()
    completions = []

    # Add main command options
    main_options = []
    for action in main_parser._actions:
        main_options.append(argument_to_completion(action))
    completions.append(f"complete -W \"{' '.join(main_options)}\" borgmatic")

    # Add subcommand options
    for subcommand in sorted(main_parser._choices_actions[0].choices.keys()):
        subparser = main_parser._choices_actions[0].choices[subcommand]
        completions.append(subcommand_completion(subcommand, subparser))

    return '\n'.join(completions)

