def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    parsed_args = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        try:
            parsed, remaining = parser.parse_known_args(unparsed_arguments)
            parsed_args[subparser_name] = parsed
            if not remaining_arguments or len(remaining) < len(remaining_arguments):
                remaining_arguments = remaining
        except Exception as e:
            # If parsing fails, we skip this subparser and move to the next
            continue

    return parsed_args, remaining_arguments

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    try:
        if not isinstance(response, list):
            raise ValueError("The response must be a list.")
        if not isinstance(max_results, int) or max_results <= 0:
            raise ValueError("Max results must be a positive integer.")

        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]
    except Exception as e:
        print(f"An error occurred: {e}")
        yield []

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        raise ValueError("Size cannot be an empty string")

    units = {
        'B': 1,
        'K': 1000,
        'KB': 1000,
        'M': 1000**2,
        'MB': 1000**2,
        'G': 1000**3,
        'GB': 1000**3,
        'T': 1000**4,
        'TB': 1000**4,
        'P': 1000**5,
        'PB': 1000**5,
        'E': 1000**6,
        'EB': 1000**6,
        'Z': 1000**7,
        'ZB': 1000**7,
        'Y': 1000**8,
        'YB': 1000**8
    }

    # Check if the last character(s) is a unit
    if size[-1].isalpha():
        try:
            number_part = size[:-1]
            unit_part = size[-1:]
            if number_part == '' or not number_part.replace('.', '', 1).isdigit():
                raise ValueError("Size must start with a number")
            if unit_part in units:
                return int(float(number_part) * units[unit_part])
            else:
                # Try to match two letter units (e.g., KB, MB)
                unit_part = size[-2:]
                if unit_part in units:
                    return int(float(number_part) * units[unit_part])
                else:
                    raise ValueError("Unknown unit: " + unit_part)
        except ValueError as e:
            raise ValueError("Invalid size format: " + str(e))
    else:
        # No unit specified, assume bytes
        if size.replace('.', '', 1).isdigit():
            return int(float(size))
        else:
            raise ValueError("Invalid size format: " + size)

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    try:
        if size[-1].isdigit():
            return int(size)
        else:
            number = float(size[:-1])
            unit = size[-1].upper()
            if unit == 'K':
                return int(number * 1000)
            elif unit == 'M':
                return int(number * 1000**2)
            elif unit == 'G':
                return int(number * 1000**3)
            elif unit == 'T':
                return int(number * 1000**4)
            elif unit == 'P':
                return int(number * 1000**5)
            else:
                raise ValueError(f"Unknown unit: {unit}")
    except (ValueError, IndexError) as e:
        raise ValueError(f"Invalid size format: {size}") from e

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        if not isinstance(d, dict):
            raise ValueError("All elements in the iterable must be dictionaries.")
        for key, value in d.items():
            if key in result:
                result[key] += value
            else:
                result[key] = value
    return result

