def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = set()
    for action in parser._actions:
        if action.option_strings:
            for option in action.option_strings:
                flags.add(option)
    return ' '.join(sorted(flags))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not isinstance(alphabet, list) or len(alphabet) < 2:
        raise ValueError("Alphabet must be a list with at least two elements.")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer or None.")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    result = []
    while number > 0:
        number, remainder = divmod(number, base)
        result.append(alphabet[remainder])

    if padding is not None and len(result) < padding:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int) or number < 0:
        raise ValueError("Number must be a non-negative integer.")
    if not alphabet:
        raise ValueError("Alphabet must be a non-empty list.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two characters.")

    if number == 0:
        result = alphabet[0]
    else:
        result = []
        while number > 0:
            digit = number % base
            number //= base
            result.append(alphabet[digit])
        result = ''.join(reversed(result))

    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError("Padding must be a non-negative integer.")
        result = result.zfill(padding)

    return result

