def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for subcls in sc:
            if subcls not in seen:
                queue.add(subcls)

    seen.remove(cls)
    return seen

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise ValueError("Input must be a class type")

    seen = set()
    queue = set([cls])

    while queue:
        c = queue.pop()
        sc = c.__subclasses__()
        for sub in sc:
            if sub not in seen:
                seen.add(sub)
                queue.add(sub)

    seen.discard(cls)
    return seen

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        current = queue.pop()
        for subclass in current.__subclasses__():
            if subclass not in seen:
                seen.add(subclass)
                queue.append(subclass)

    return seen - {cls}

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    stack = [cls]

    while stack:
        parent = stack.pop()
        for child in parent.__subclasses__():
            if child not in seen:
                seen.add(child)
                stack.append(child)

    return seen

def subclasses(cls):
