    """
    if not alphabet or not string:
        raise ValueError("Both string and alphabet must be non-empty.")

    base = len(alphabet)
    alphabet_map = {char: index for index, char in enumerate(alphabet)}

    number = 0
    for char in string:
        if char not in alphabet_map:
            raise ValueError(f"Character '{char}' in string is not in the provided alphabet.")
        number = number * base + alphabet_map[char]

    return number

