def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:  # POSIX
        # Regex for splitting POSIX command lines
        regex = r'''(?u)(?:"([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|(\\ |\S)+'''
    elif platform == 0:  # Windows/CMD
        # Regex for splitting Windows command lines
        regex = r'''(?u)("([^"\\]*(?:\\.[^"\\]*)*)"|'([^'\\]*(?:\\.[^'\\]*)*)'|(\S+))'''
    else:
        raise ValueError("Unsupported platform value")

    try:
        result = re.findall(regex, s)
        # Flatten the result and remove empty strings
        return list(filter(None, [item for sublist in result for item in sublist if item]))
    except re.error as e:
        raise ValueError("Regex error: {}".format(e))

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import subprocess
    from pathlib import Path

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive {archive_path} does not exist.")

    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    tmp_path.mkdir(parents=True, exist_ok=True)

    if filename is None:
        filename = os.path.basename(archive_path)

    extract_path = tmp_path / os.path.splitext(filename)[0]
    extract_path.mkdir(parents=True, exist_ok=True)

    try:
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(extract_path)], check=True)
        elif archive_path.endswith('.tar.bz2'):
            subprocess.run(['tar', '-xjf', archive_path, '-C', str(extract_path)], check=True)
        elif archive_path.endswith('.zip'):
            subprocess.run(['unzip', archive_path, '-d', str(extract_path)], check=True)
        else:
            raise ValueError(f"Unsupported archive type for file: {archive_path}")
    except subprocess.CalledProcessError as e:
        shutil.rmtree(extract_path, ignore_errors=True)
        raise RuntimeError(f"Failed to extract archive {archive_path}: {e}")

    return f"file://{extract_path.resolve()}"

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import os
    import shutil
    import subprocess
    from pathlib import Path

    tmp_path = Path(tmp_path)
    if not tmp_path.exists():
        tmp_path.mkdir(parents=True, exist_ok=True)

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive does not exist at {archive_path}")

    try:
        # Determine the archive type and extract accordingly
        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            shutil.unpack_archive(archive_path, extract_dir=tmp_path, format='gztar')
        elif archive_path.endswith('.tar.bz2') or archive_path.endswith('.tbz2'):
            shutil.unpack_archive(archive_path, extract_dir=tmp_path, format='bztar')
        elif archive_path.endswith('.zip'):
            shutil.unpack_archive(archive_path, extract_dir=tmp_path, format='zip')
        else:
            # Fallback to using tar command for other tar types
            subprocess.run(['tar', '-xvf', archive_path, '-C', str(tmp_path)], check=True)
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Failed to extract archive {archive_path}: {e}")

    # Determine the path of the extracted repository
    if filename:
        repo_path = tmp_path / filename
    else:
        # Assuming the archive contains a single directory or file
        contents = list(tmp_path.iterdir())
        if len(contents) == 1:
            repo_path = contents[0]
        else:
            raise ValueError("Archive should contain a single directory or file, or filename must be specified")

    if not repo_path.exists():
        raise ValueError(f"Extracted repository not found at {repo_path}")

    return repo_path.as_uri()

def prepare_repository_from_archive(
