    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    import subprocess
    import os
    from pathlib import Path

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive path {archive_path} does not exist.")

    if isinstance(tmp_path, str):
        tmp_path = Path(tmp_path)

    if not tmp_path.exists():
        raise FileNotFoundError(f"The temporary path {tmp_path} does not exist.")

    tmp_path = tmp_path / os.path.basename(archive_path)
    tmp_path.mkdir(exist_ok=True)

    try:
        if filename is None:
            filename = os.path.basename(archive_path)

        output_path = tmp_path / filename
        with output_path.open('wb') as f:
            # Assuming the archive is a tarball for this example
            subprocess.run(['tar', '-xzf', archive_path, '-C', str(tmp_path)], check=True)

        # Assuming the repository is a directory named after the filename without extension
        repo_name = os.path.splitext(filename)[0]
        repo_path = tmp_path / repo_name
        if repo_path.exists() and repo_path.is_dir():
            return str(repo_path)
        else:
            raise ValueError(f"Repository directory {repo_name} not found in the archive.")

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive: {e}") from e
    except Exception as e:
        raise Exception(f"An error occurred: {e}") from e

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(["git", "check-ignore", "-v"] + ignored, stderr=subprocess.STDOUT, text=True)
        ignored_files = set()
        for line in output.splitlines():
            if line.split() and line.split()[3] in ignored:
                ignored_files.add(line.split()[3])
        return ','.join(sorted(ignored_files))
    except subprocess.CalledProcessError as e:
        return "Error: " + e.output.strip()
    except Exception as e:
        return "An unexpected error occurred: " + str(e)

