        output, status = subprocess.getstatusoutput("git check-ignore -v *")
        if status != 0:
            raise Exception(f"Failed to check ignored files: {output}")

        ignored_files = set()
        for line in output.split('\n'):
            if line:
                parts = line.split()
                if len(parts) >= 3 and parts[2] not in ignored:
                    ignored_files.add(parts[2])

        return ','.join(sorted(ignored_files))
    except Exception as e:
        return str(e)

