def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    import re
    match = re.match(r"^\s*(\d+)\s*([a-zA-Z]+)\s*$", frequency)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    number, unit = match.groups()
    number = int(number)
    unit = unit.lower().strip('s')  # Remove plural 's' if present

    try:
        if unit == "second" or unit == "sec":
            return datetime.timedelta(seconds=number)
        elif unit == "minute" or unit == "min":
            return datetime.timedelta(minutes=number)
        elif unit == "hour" or unit == "hr":
            return datetime.timedelta(hours=number)
        elif unit == "day":
            return datetime.timedelta(days=number)
        elif unit == "week":
            return datetime.timedelta(weeks=number)
        else:
            raise ValueError(f"Unknown time unit: {unit}")
    except ValueError as e:
        raise ValueError(f"Cannot parse frequency: {frequency}") from e

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        value, unit = frequency.split()
        value = int(value)
    except (ValueError, TypeError):
        raise ValueError(f"Cannot parse frequency: {frequency}")

    unit = unit.strip().lower()
    if unit.endswith('s'):
        unit = unit[:-1]  # Remove plural 's'

    if unit in ['second', 'minute', 'hour', 'day', 'week']:
        return datetime.timedelta(**{unit + 's': value})
    elif unit in ['month', 'year']:
        # Approximate months and years as days to create a timedelta
        # 1 month is approximately 30 days, 1 year is approximately 365 days
        days = value * (365 if unit == 'year' else 30)
        return datetime.timedelta(days=days)
    else:
        raise ValueError(f"Unknown time unit: {unit}")

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency format")

    try:
        value = int(parts[0])
    except ValueError:
        raise ValueError("Frequency value must be an integer")

    unit = parts[1].strip().lower()
    if unit.endswith('s'):
        unit = unit[:-1]  # Remove plural form if it exists

    try:
        return datetime.timedelta(**{unit: value})
    except TypeError:
        raise ValueError(f"Unknown time unit: {unit}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        addr_info = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for entry in addr_info:
        family, _, _, _, sockaddr = entry
        if family == socket.AF_INET:
            if sockaddr[0] in ('127.0.0.1', '0.0.0.0'):
                return True
        elif family == socket.AF_INET6:
            if sockaddr[0] == '::1':
                return True

    return False

