    """
    try:
        if not hasattr(candidate, '__implements__'):
            candidate.__implements__ = ()
        if iface not in candidate.__implements__:
            raise NotImplementedError(f"Candidate does not implement the interface {iface.__name__}")
    except Exception as e:
        if not tentative:
            raise ValueError(f"Verification failed: {str(e)}")
        return False
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not issubclass(candidate, iface):
        error_message = f"Candidate class {candidate.__name__} does not implement interface {iface.__name__}."
        if tentative:
            return False
        else:
            raise TypeError(error_message)

    for attr in dir(iface):
        if attr.startswith('__') and attr.endswith('__'):
            continue  # Skip special methods
        if not hasattr(candidate, attr):
            error_message = f"Candidate class {candidate.__name__} is missing attribute {attr} from interface {iface.__name__}."
            if tentative:
                return False
            else:
                raise AttributeError(error_message)

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if not hasattr(iface, '__provides__'):
            raise ValueError("iface must be an interface with __provides__")
        if not isinstance(candidate, type):
            raise ValueError("candidate must be a class")

        # Check if candidate implements all the attributes and methods of iface
        for attr in iface.__provides__:
            if not hasattr(candidate, attr):
                if not tentative:
                    raise AttributeError(f"Candidate class {candidate.__name__} does not implement {attr} required by {iface.__name__}")
                return False
        return True
    except Exception as e:
        raise RuntimeError(f"Error verifying class: {e}")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclass = None
    for base in bases:
        try:
            if metaclass is None:
                metaclass = getattr(base, '__class__', None)
            elif metaclass is not getattr(base, '__class__', None):
                raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of all the metaclasses of its bases")
        except AttributeError:
            continue

    if metaclass is None:
        raise TypeError("metaclass not found")

    return metaclass

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        try:
            metaclass = type(base)
            if metaclass not in metaclasses:
                metaclasses.add(metaclass)
        except TypeError:
            # Skip if the base is not a class type
            continue

    if not metaclasses:
        return type

    # If there's more than one metaclass, we need to find a common one
    if len(metaclasses) > 1:
        common_metaclass = None
        for m in metaclasses:
            if all(issubclass(c, m) for c in metaclasses):
                if common_metaclass is None or issubclass(m, common_metaclass):
                    common_metaclass = m
        if common_metaclass is not None:
            return common_metaclass

    # If no common metaclass is found, raise a TypeError
    raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of all the metaclasses of its bases")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        if hasattr(base, '__class__'):
            metaclass = base.__class__
            if isinstance(metaclass, type):
                metaclasses.add(metaclass)

    if not metaclasses:
        return type

    common_metaclass = None
    for meta in metaclasses:
        if common_metaclass is None:
            common_metaclass = meta
        elif not issubclass(meta, common_metaclass):
            if issubclass(common_metaclass, meta):
                common_metaclass = meta
            else:
                raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

    return common_metaclass

def determineMetaclass(bases, explicit_mc=None):
