    if explicit_mc is not None:
        return explicit_mc

    metaclass = None
    for base in bases:
        try:
            mcs = base.__class__
            if metaclass is None:
                metaclass = mcs
            elif metaclass is not mcs:
                raise TypeError("metaclass conflict: the metaclass of a derived class must be a subclass of all metaclasses of its bases")
        except AttributeError:
