    import re
    import os

    def to_url(m):
        path = m.group(0)
        if re.match(r'https?://', path):
            return path
        if os.path.exists(path):
            return f'/browse/{os.path.relpath(path)}'
        return None

    def add_attributes(url):
        if url:
            return f'<a href="{url}" target="_blank">{url}</a>'
        return m.group(0)

    # Regex to find URLs and file paths
    url_pattern = re.compile(r'https?://[\w.-]+(?:\/[!\w.-]*)*|\/[\w.-]+(?:\/[!\w.-]*)*')
