            return None
        return '/browse/{}'.format(os.path.relpath(path))

    def maybe_add_link(url, text):
        if url:
            attrs = link_attrs_callback(url)
            return '<a href="{}" {}>{}</a>'.format(url, attrs, text)
        return text

    import re
    url_pattern = re.compile(r'\bhttps?://[^\s]+|\b/\S+|\b\.\./\S+|\b\w+:\w+')
    return url_pattern.sub(lambda m: maybe_add_link(to_url(m), m.group(0)), text)

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    import requests
    try:
