    :param settings_dirs: List of directories to search for files
    :param spec_option: Specification option to filter files
    :return: List of fully qualified filenames
    """
    import os

    if not isinstance(settings_dirs, list):
        raise ValueError("settings_dirs must be a list of directories.")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string.")

    file_names = []
    for directory in settings_dirs:
        if not os.path.isdir(directory):
            raise ValueError(f"{directory} is not a valid directory.")
        try:
            for fname in os.listdir(directory):
                if fname.endswith(spec_option):
                    file_names.append(os.path.join(directory, fname))
        except OSError as e:
            print(f"Error accessing {directory}: {e}")
            continue

    return sorted(file_names)

