def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    try:
        parser = self.parsers[parser_name]
    except KeyError:
        raise ValueError(f"No parser found for command: {parser_name}")

    for arg, value in values_dict.items():
        try:
            action = next(action for action in parser._actions if action.dest == arg)
        except StopIteration:
            continue  # Ignore arguments not found in the parser

        try:
            # Convert the value using the parser's type conversion
            if action.type:
                values_dict[arg] = action.type(value)
            elif action.choices:
                if value not in action.choices:
                    raise ValueError(f"Invalid choice for {arg}: {value}")
            elif action.nargs == 0 and action.const is not None:
                values_dict[arg] = action.const
        except (ValueError, TypeError) as e:
            raise ValueError(f"Error converting argument '{arg}': {e}")

